    -- Marquee Text System (Text Running Effect)
    local MarqueeSystem = {}
    MarqueeSystem.__index = MarqueeSystem
    
    function MarqueeSystem.new(parent, text, options)
        options = options or {}
        local self = setmetatable({}, MarqueeSystem)
        
        self.container = Instance.new("Frame")
        self.container.Name = "MarqueeContainer"
        self.container.Size = options.size or UDim2.new(1, -100, 0, 50)
        self.container.Position = options.position or UDim2.new(0, 50, 0, 5)
        self.container.BackgroundTransparency = 1
        self.container.ClipsDescendants = true
        self.container.Parent = parent
        
        self.text = text
        self.speed = options.speed or 50
        self.delayTime = options.delay or 3
        self.isRunning = false
        
        -- Create text label
        self.textLabel = Instance.new("TextLabel")
        self.textLabel.Size = UDim2.new(0, 0, 1, 0)
        self.textLabel.Position = UDim2.new(0, 0, 0, 0)
        self.textLabel.BackgroundTransparency = 1
        self.textLabel.Text = self.text
        self.textLabel.TextColor3 = options.textColor or Colors.textPrimary
        self.textLabel.TextSize = options.textSize or 22
        self.textLabel.Font = Enum.Font.GothamBold
        self.textLabel.TextXAlignment = Enum.TextXAlignment.Left
        self.textLabel.TextYAlignment = Enum.TextYAlignment.Center
        self.textLabel.Parent = self.container
        
        -- Get text width
        local textSize = TextService:GetTextSize(self.text, self.textLabel.TextSize, self.textLabel.Font, Vector2.new(10000, 100))
        self.textWidth = textSize.X
        
        -- Resize container if text is too wide
        if self.textWidth > self.container.AbsoluteSize.X then
            self.textLabel.Size = UDim2.new(0, self.textWidth, 1, 0)
            self.needsMarquee = true
        else
            self.textLabel.Size = UDim2.new(1, 0, 1, 0)
            self.needsMarquee = false
        end
        
        return self
    end
    
    function MarqueeSystem:start()
        if self.isRunning then return end
        if not self.needsMarquee then
            -- Just center the text
            self.textLabel.Position = UDim2.new(0.5, -self.textWidth/2, 0, 0)
            return
        end
        
        self.isRunning = true
        local containerWidth = self.container.AbsoluteSize.X
        local textWidth = self.textWidth
        
        local function runMarquee()
            while self.isRunning do
                -- Start from right side (outside view)
                self.textLabel.Position = UDim2.new(1, 0, 0, 0)
                
                -- Wait a bit before starting
                task.wait(0.5)
                
                -- Calculate animation time based on speed
                local totalDistance = textWidth + containerWidth
                local duration = totalDistance / self.speed
                
                -- Animate text from right to left
                TweenService:Create(self.textLabel, TweenInfo.new(duration, Enum.EasingStyle.Linear), {
                    Position = UDim2.new(0, -textWidth, 0, 0)
                }):Play()
                
                -- Wait for animation to complete plus delay
                task.wait(duration + self.delayTime)
            end
        end
        
        task.spawn(runMarquee)
    end
    
    function MarqueeSystem:stop()
        self.isRunning = false
    end
    
    function MarqueeSystem:updateText(newText)
        self.text = newText
        self.textLabel.Text = newText
        
        -- Update text width
        local textSize = TextService:GetTextSize(self.text, self.textLabel.TextSize, self.textLabel.Font, Vector2.new(10000, 100))
        self.textWidth = textSize.X
        
        self.textLabel.Size = UDim2.new(0, self.textWidth, 1, 0)
        
        -- Check if needs marquee
        if self.textWidth > self.container.AbsoluteSize.X then
            self.needsMarquee = true
            if self.isRunning then
                self:stop()
                self:start()
            end
        else
            self.needsMarquee = false
            self.textLabel.Position = UDim2.new(0.5, -self.textWidth/2, 0, 0)
        end
    end

