    function UI:setupEnhancedEffects()
        -- Close Button Effects
        local closeBtn = self.elements.closeButton
        closeBtn.MouseEnter:Connect(function()
            TweenService:Create(closeBtn, TweenInfo.new(0.2), {
                BackgroundColor3 = Color3.fromRGB(255, 100, 100),
                Size = UDim2.new(0, 38, 0, 38)
            }):Play()
        end)
        
        closeBtn.MouseLeave:Connect(function()
            TweenService:Create(closeBtn, TweenInfo.new(0.2), {
                BackgroundColor3 = Colors.error,
                Size = UDim2.new(0, 34, 0, 34)
            }):Play()
        end)
        
        -- Get Link Button Effects
        local getLinkBtn = self.elements.getLinkButton
        local getLinkIcon = self.elements.getLinkIcon
        
        getLinkBtn.MouseEnter:Connect(function()
            TweenService:Create(getLinkBtn, TweenInfo.new(0.2), {
                BackgroundColor3 = Colors.primaryLight
            }):Play()
            
            getLinkIcon.Visible = true
            TweenService:Create(getLinkIcon, TweenInfo.new(0.3), {
                Position = UDim2.new(0, 15, 0.5, 0)
            }):Play()
            
            getLinkBtn.Text = " Get Premium Link"
        end)
        
        getLinkBtn.MouseLeave:Connect(function()
            TweenService:Create(getLinkBtn, TweenInfo.new(0.2), {
                BackgroundColor3 = Colors.primary
            }):Play()
            
            TweenService:Create(getLinkIcon, TweenInfo.new(0.2), {
                Position = UDim2.new(0, -20, 0.5, 0)
            }):Play()
            
            task.delay(0.2, function()
                if getLinkBtn then
                    getLinkIcon.Visible = false
                    getLinkBtn.Text = Icons.getLink .. " Get Premium Link"
                end
            end)
        end)
        
        -- Verify Button Effects
        local verifyBtn = self.elements.verifyButton
        local verifyIcon = self.elements.verifyIcon
        
        verifyBtn.MouseEnter:Connect(function()
            TweenService:Create(verifyBtn, TweenInfo.new(0.2), {
                BackgroundColor3 = Colors.successLight
            }):Play()
            
            verifyIcon.Visible = true
            TweenService:Create(verifyIcon, TweenInfo.new(0.3), {
                Position = UDim2.new(0, 15, 0.5, 0)
            }):Play()
            
            verifyBtn.Text = " Verify Key"
        end)
        
        verifyBtn.MouseLeave:Connect(function()
            TweenService:Create(verifyBtn, TweenInfo.new(0.2), {
                BackgroundColor3 = Colors.success
            }):Play()
            
            TweenService:Create(verifyIcon, TweenInfo.new(0.2), {
                Position = UDim2.new(0, -20, 0.5, 0)
            }):Play()
            
            task.delay(0.2, function()
                if verifyBtn then
                    verifyIcon.Visible = false
                    verifyBtn.Text = Icons.verify .. " Verify Key"
                end
            end)
        end)
        
        -- Input Field Effects
        local inputCard = self.elements.inputCard
        local inputStroke = self.elements.inputStroke
        
        self.elements.keyInput.Focused:Connect(function()
            TweenService:Create(inputStroke, TweenInfo.new(0.2), {
                Color = Colors.primary,
                Thickness = 2
            }):Play()
            
            TweenService:Create(inputCard, TweenInfo.new(0.2), {
                BackgroundTransparency = 0
            }):Play()
        end)
        
        self.elements.keyInput.FocusLost:Connect(function()
            TweenService:Create(inputStroke, TweenInfo.new(0.2), {
                Color = Colors.border,
                Thickness = 1
            }):Play()
            
            TweenService:Create(inputCard, TweenInfo.new(0.2), {
                BackgroundTransparency = 0.1
            }):Play()
        end)
        
        -- Ripple effect for buttons
        local buttons = {getLinkBtn, verifyBtn, closeBtn}
        for _, button in ipairs(buttons) do
            button.MouseButton1Down:Connect(function(x, y)
                local absolutePos = button.AbsolutePosition
                local absoluteSize = button.AbsoluteSize
                local mousePos = UserInputService:GetMouseLocation()
                
                local relativeX = mousePos.X - absolutePos.X
                local relativeY = mousePos.Y - absolutePos.Y
                
                RippleSystem.createRipple(button, Vector2.new(relativeX, relativeY))
            end)
        end
        
        -- Particle effects for buttons
        self.particleSystem:createButtonParticles(getLinkBtn)
        self.particleSystem:createButtonParticles(verifyBtn)
        self.particleSystem:createButtonParticles(closeBtn)
        
        -- Avatar hover effect
        local avatarFrame = self.elements.avatarFrame
        if avatarFrame then
            avatarFrame.MouseEnter:Connect(function()
                TweenService:Create(avatarFrame, TweenInfo.new(0.2), {
                    Size = UDim2.new(0, 52, 0, 52)
                }):Play()
            end)
            
            avatarFrame.MouseLeave:Connect(function()
                TweenService:Create(avatarFrame, TweenInfo.new(0.2), {
                    Size = UDim2.new(0, 48, 0, 48)
                }):Play()
            end)
        end
        
        -- Subtitle animation (glow effect)
        local subtitle = self.elements.subtitle
        if subtitle then
            -- Subtle glow animation
            local glowTween = TweenService:Create(subtitle, TweenInfo.new(2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
                TextTransparency = 0.2
            })
            glowTween:Play()
        end
    end
    
    function UI:connectEvents()
        -- Close button
        self.elements.closeButton.MouseButton1Click:Connect(function()
            self:close()
        end)
        
        -- Get Link button
        self.elements.getLinkButton.MouseButton1Click:Connect(function()
            self:handleGetLink()
        end)
        
        -- Verify button
        self.elements.verifyButton.MouseButton1Click:Connect(function()
            self:handleVerify()
        end)
        
        -- Enter key in input
        self.elements.keyInput.FocusLost:Connect(function(enterPressed)
            if enterPressed and not self.isVerifying then
                self:handleVerify()
            end
        end)
        
        -- Escape key to close
        local escapeConnection
        escapeConnection = UserInputService.InputBegan:Connect(function(input)
            if input.KeyCode == Enum.KeyCode.Escape then
                self:close()
                escapeConnection:Disconnect()
            end
        end)
        
        table.insert(self.connections, escapeConnection)
    end
    
    function UI:animateEntrance()
        -- Initial hidden state
        self.elements.container.Position = UDim2.new(0.5, 0, 0.5, -100)
        self.elements.container.Rotation = -5
        self.elements.container.BackgroundTransparency = 1
        self.elements.background.BackgroundTransparency = 1
        
        -- Animate background
        TweenService:Create(self.elements.background, TweenInfo.new(0.5), {
            BackgroundTransparency = 0.7
        }):Play()
        
        -- Animate container with bounce effect
        TweenService:Create(self.elements.container, TweenInfo.new(0.6, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
            BackgroundTransparency = 0.1,
            Position = UDim2.new(0.5, 0, 0.5, 0),
            Rotation = 0
        }):Play()
        
        -- Particle burst on entrance
        task.delay(0.3, function()
            if self.particleSystem then
                local centerX = self.elements.container.AbsolutePosition.X + self.elements.container.AbsoluteSize.X / 2
                local centerY = self.elements.container.AbsolutePosition.Y + self.elements.container.AbsoluteSize.Y / 2
                
                self.particleSystem:emit(
                    UDim2.new(0, centerX, 0, centerY),
                    ParticleColors.primary,
                    20,
                    1.5,
                    8,
                    1.2
                )
            end
        end)
        
        -- Start marquee effect after entrance animation
        task.delay(0.8, function()
            if self.marqueeSystem then
                self.marqueeSystem:start()
            end
        end)
    end
    
    function UI:updateRetryUI(attempt, maxAttempts, isActive)
        if self.elements and self.elements.retryCard then
            if isActive then
                self.elements.retryCard.Visible = true
                self.elements.retryText.Text = "Auto-retry: " .. attempt .. "/" .. maxAttempts
                
                -- Pulse animation
                local pulseTween = TweenService:Create(self.elements.retryCard, TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                    BackgroundTransparency = 0.85
                })
                
                local reverseTween = TweenService:Create(self.elements.retryCard, TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                    BackgroundTransparency = 0.9
                })
                
                pulseTween:Play()
                pulseTween.Completed:Connect(function()
                    reverseTween:Play()
                end)
            else
                self.elements.retryCard.Visible = false
            end
        end
    end
    
    function UI:showStatus(message, icon, color, duration)
        if self.elements and self.elements.statusCard then
            self.elements.statusIcon.Text = icon or Icons.info
            self.elements.statusText.Text = message
            self.elements.statusText.TextColor3 = color or Colors.textSecondary
            self.elements.statusCard.BackgroundColor3 = color or Colors.surfaceLight
            self.elements.statusCard.Visible = true
            
            -- Fade in
            self.elements.statusCard.BackgroundTransparency = 1
            TweenService:Create(self.elements.statusCard, TweenInfo.new(0.3), {
                BackgroundTransparency = 0.9
            }):Play()
            
            if duration and duration > 0 then
                task.delay(duration, function()
                    if self.elements and self.elements.statusCard then
                        TweenService:Create(self.elements.statusCard, TweenInfo.new(0.3), {
                            BackgroundTransparency = 1
                        }):Play()
                        
                        task.delay(0.3, function()
                            if self.elements and self.elements.statusCard then
                                self.elements.statusCard.Visible = false
                            end
                        end)
                    end
                end)
            end
        end
    end
    
    function UI:showWarning(message, duration)
        if self.elements and self.elements.warningCard then
            self.elements.warningIcon.Text = Icons.warning .. Icons.fire
            self.elements.warningText.Text = message
            self.elements.warningCard.Visible = true
            
            -- Shake animation
            local origPos = self.elements.warningCard.Position
            for i = 1, 3 do
                TweenService:Create(self.elements.warningCard, TweenInfo.new(0.05), {
                    Position = UDim2.new(origPos.X.Scale, origPos.X.Offset - 3, origPos.Y.Scale, origPos.Y.Offset)
                }):Play()
                task.wait(0.05)
                TweenService:Create(self.elements.warningCard, TweenInfo.new(0.05), {
                    Position = UDim2.new(origPos.X.Scale, origPos.X.Offset + 3, origPos.Y.Scale, origPos.Y.Offset)
                }):Play()
                task.wait(0.05)
            end
            self.elements.warningCard.Position = origPos
            
            if duration and duration > 0 then
                task.delay(duration, function()
                    if self.elements and self.elements.warningCard then
                        TweenService:Create(self.elements.warningCard, TweenInfo.new(0.3), {
                            BackgroundTransparency = 1
                        }):Play()
                        
                        task.delay(0.3, function()
                            if self.elements and self.elements.warningCard then
                                self.elements.warningCard.Visible = false
                            end
                        end)
                    end
                end)
            end
        end
    end
    
    function UI:shakeInput()
        local frame = self.elements.inputCard
        if not frame then return end
        
        local origPos = frame.Position
        for i = 1, 5 do
            local offset = math.random(-8, 8)
            TweenService:Create(frame, TweenInfo.new(0.05), {
                Position = UDim2.new(origPos.X.Scale, origPos.X.Offset + offset, origPos.Y.Scale, origPos.Y.Offset)
            }):Play()
            task.wait(0.05)
        end
        frame.Position = origPos
        
        -- Red flash effect
        local origColor = self.elements.inputStroke.Color
        TweenService:Create(self.elements.inputStroke, TweenInfo.new(0.1), {
            Color = Colors.error
        }):Play()
        
        task.wait(0.1)
        
        TweenService:Create(self.elements.inputStroke, TweenInfo.new(0.3), {
            Color = origColor
        }):Play()
    end
    
    function UI:setLoading(state)
        self.isVerifying = state
        
        if state then
            self.elements.verifyButton.Text = Icons.verifyLoading .. " Checking..."
            self.elements.verifyButton.Interactable = false
            self.elements.getLinkButton.Interactable = false
            self.elements.keyInput.Interactable = false
            self.elements.closeButton.Interactable = false
            
            -- Loading animation
            local rotation = 0
            local connection
            connection = RunService.RenderStepped:Connect(function(delta)
                rotation = (rotation + 360 * delta) % 360
                self.elements.verifyButton.Rotation = rotation
            end)
            
            table.insert(self.connections, connection)
        else
            self.elements.verifyButton.Text = Icons.verify .. " Verify Key"
            self.elements.verifyButton.Interactable = true
            self.elements.getLinkButton.Interactable = true
            self.elements.keyInput.Interactable = true
            self.elements.closeButton.Interactable = true
            self.elements.verifyButton.Rotation = 0
            
            -- Disconnect loading animation
            for _, conn in ipairs(self.connections) do
                if conn then
                    conn:Disconnect()
                end
            end
        end
    end
    
    function UI:handleGetLink()
        local link = Junkie.get_key_link()
        
        if not link then
            self:showWarning("Failed to get premium link", 3)
            return
        end
        
        -- Particle effect
        local buttonPos = self.elements.getLinkButton.AbsolutePosition
        local buttonSize = self.elements.getLinkButton.AbsoluteSize
        local centerX = buttonPos.x + buttonSize.x / 2
        local centerY = buttonPos.y + buttonSize.y / 2
        
        self.particleSystem:emit(
            UDim2.new(0, centerX, 0, centerY),
            ParticleColors.primary,
            12,
            1.2,
            6,
            0.8
        )
        
        if setclipboard then
            setclipboard(link)
            self:showStatus("✅ Premium link copied to clipboard!", Icons.diamond, Colors.success, 3)
        else
            self:showStatus("Link: " .. link, Icons.link, Colors.primary, 5)
        end
    end
    
    function UI:handleVerify()
        if self.isVerifying then return end
        
        local key = self.elements.keyInput.Text:gsub("%s+", "")
        
        if key == "" then
            self:showWarning("Please enter a premium key", 3)
            self:shakeInput()
            return
        end
        
        if #key < 10 then
            self:showWarning("Key is too short", 3)
            self:shakeInput()
            return
        end
        
        -- Start verification
        self:setLoading(true)
        self.retryCount = 0
        self:showStatus("Verifying premium key...", Icons.shield, Colors.primary, 0)
        
        local function performCheckWithRetry(attempt)
            if attempt > 0 then
                self:updateRetryUI(attempt, self.maxRetries, true)
                self:showStatus("Retry attempt " .. attempt .. "/" .. self.maxRetries, Icons.retry, Colors.warning, 0)
                task.wait(RETRY_DELAY)
            end
            
            local result, message = checkKeyWithRetry(key, attempt)
            
            if result and result.valid then
                -- Success effects
                saveKey(key)
                self:updateRetryUI(0, self.maxRetries, false)
                self:showStatus("✅ Premium access granted!", Icons.trophy, Colors.success, 0)
                
                -- Success particle burst
                local buttonPos = self.elements.verifyButton.AbsolutePosition
                local buttonSize = self.elements.verifyButton.AbsoluteSize
                local centerX = buttonPos.x + buttonSize.x / 2
                local centerY = buttonPos.y + buttonSize.y / 2
                
                self.particleSystem:emit(
                    UDim2.new(0, centerX, 0, centerY),
                    ParticleColors.success,
                    20,
                    1.5,
                    8,
                    1.5
                )
                
                -- Input success animation
                TweenService:Create(self.elements.keyInput, TweenInfo.new(0.3), {
                    TextColor3 = Colors.success
                }):Play()
                
                TweenService:Create(self.elements.inputStroke, TweenInfo.new(0.3), {
                    Color = Colors.success,
                    Thickness = 3
                }):Play()
                
                -- Avatar celebration animation
                local avatarFrame = self.elements.avatarFrame
                if avatarFrame then
                    TweenService:Create(avatarFrame, TweenInfo.new(0.5, Enum.EasingStyle.Elastic, Enum.EasingDirection.Out), {
                        Size = UDim2.new(0, 56, 0, 56),
                        Rotation = 360
                    }):Play()
                    
                    task.wait(0.5)
                    
                    TweenService:Create(avatarFrame, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                        Size = UDim2.new(0, 48, 0, 48),
                        Rotation = 0
                    }):Play()
                end
                
                -- Change marquee text to success message
                if self.marqueeSystem then
                    self.marqueeSystem:updateText("✅ ACCESS GRANTED ✅")
                end
                
                -- Wait and close
                task.wait(2)
                getgenv().SCRIPT_KEY = key
                self:close()
                return true
            elseif attempt < self.maxRetries then
                return performCheckWithRetry(attempt + 1)
            else
                self:updateRetryUI(0, self.maxRetries, false)
                self:showWarning("Invalid key (tried " .. (self.maxRetries + 1) .. " times)", 5)
                self:shakeInput()
                
                self:setLoading(false)
                self:showStatus("All retry attempts failed", Icons.error, Colors.error, 2)
                return false
            end
        end
        
        task.spawn(function()
            performCheckWithRetry(0)
        end)
    end
    
    function UI:close()
        getgenv().UI_CLOSED = true
        
        -- Stop marquee system
        if self.marqueeSystem then
            self.marqueeSystem:stop()
        end
        
        -- Disconnect all connections
        for _, conn in ipairs(self.connections) do
            if conn then
                conn:Disconnect()
            end
        end
        
        if self.elements and self.elements.container then
            -- Exit animation
            TweenService:Create(self.elements.container, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.In), {
                BackgroundTransparency = 1,
                Position = UDim2.new(0.5, 0, 0.5, 100),
                Rotation = 5
            }):Play()
            
            TweenService:Create(self.elements.background, TweenInfo.new(0.4), {
                BackgroundTransparency = 1
            }):Play()
            
            task.wait(0.4)
        end
        
        if self.gui then
            self.gui:Destroy()
        end
    end

    -- ========== MAIN EXECUTION ==========
    print("[Vampire Key System] Starting with marquee effect...")
    
    local ui = UI.new()
    ui:create()
    
    task.wait(0.5)
    ui:showStatus("Checking keyless mode...", Icons.magic, Colors.primary, 2)
    
    local keylessResult = checkKeyWithRetry("KEYLESS", 0)
    if keylessResult and keylessResult.valid and keylessResult.message == "KEYLESS" then
        print("[Vampire Key System] Keyless mode active")
        ui:showStatus("✅ Keyless mode active", Icons.unlock, Colors.success, 2)
        task.wait(1.5)
        getgenv().SCRIPT_KEY = "KEYLESS"
        ui:close()
        return getgenv().SCRIPT_KEY
    end
    
    ui:showStatus("Checking saved key...", Icons.download, Colors.primary, 2)
    task.wait(1)
    
    local savedKey, savedUsername, savedUserId = loadKey()
    
    if savedKey and savedUsername then
        if savedUsername == currentPlayerName then
            ui:showStatus("Found saved key, verifying...", Icons.key, Colors.primary, 0)
            
            if ui.elements and ui.elements.keyInput then
                ui.elements.keyInput.Text = savedKey
            end
            
            task.wait(1)
            
            local function checkSavedKeyWithRetry(attempt)
                if attempt > 0 then
                    ui:updateRetryUI(attempt, MAX_RETRY_ATTEMPTS, true)
                    ui:showStatus("Retrying saved key (" .. attempt .. "/" .. MAX_RETRY_ATTEMPTS .. ")", Icons.retry, Colors.warning, 0)
                    task.wait(RETRY_DELAY)
                end
                
                local result, message = checkKeyWithRetry(savedKey, attempt)
                
                if result and result.valid then
                    print("[Vampire Key System] Saved key is valid")
                    ui:updateRetryUI(0, MAX_RETRY_ATTEMPTS, false)
                    ui:showStatus("✅ Welcome back " .. currentPlayerName .. "!", Icons.heart, Colors.success, 0)
                    
                    task.wait(1.5)
                    getgenv().SCRIPT_KEY = savedKey
                    ui:close()
                    return true
                elseif attempt < MAX_RETRY_ATTEMPTS then
                    return checkSavedKeyWithRetry(attempt + 1)
                else
                    print("[Vampire Key System] Saved key is invalid after retries")
                    clearKey()
                    ui:updateRetryUI(0, MAX_RETRY_ATTEMPTS, false)
                    ui:showWarning("Saved key has expired", 3)
                    ui:showStatus("Please enter a new premium key", Icons.info, Colors.textSecondary, 2)
                    return false
                end
            end
            
            checkSavedKeyWithRetry(0)
        else
            print("[Vampire Key System] Key belongs to another user: " .. savedUsername)
            ui:showWarning("Key belongs to: " .. savedUsername, 3)
            task.wait(1)
            ui:showStatus("Ready for key verification", Icons.star, Colors.textSecondary, 2)
        end
    else
        print("[Vampire Key System] No saved key found")
        ui:showStatus("Ready for premium key verification", Icons.star, Colors.textSecondary, 2)
    end
    
    print("[Vampire Key System] Waiting for user input...")
    while not getgenv().UI_CLOSED do
        task.wait(0.1)
    end
    
    print("[Vampire Key System] Closed")
    return getgenv().SCRIPT_KEY
end)()

